fn longest(strings: Vec<Vec<char>>) -> Option<Vec<char>> {
    if strings.len() == 0 {
        // Empty input means no longest string
        None
    } else {
        // Keep track of the index of the longest string found so far
        // Start with the first element
        let mut longest_idx = 0;

        // Iterate over the rest of the strings
        let len = strings.len();
        let mut i = 1;
        while i < len {
            // If current string is longer than the current longest,
            // update longest_idx
            if strings[i].len() > strings[longest_idx].len() {
                longest_idx = i;
            }
            i += 1;
        }

        // Return a clone of the longest string found at longest_idx
        Some(strings[longest_idx].clone())
    }
}